function beginBluetoothGuest(address: string, targetName: string): void {
  const bridge = nativeBluetooth();
  if (!bridge) return showToast("蓝牙双机模式只能在 Android 安装包内使用。");
  bluetooth = {
    role: "guest",
    nativeState: "CONNECTING",
